INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 43, 'theory', 'Quiz: Data and PostgreSQL');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 43, 0, 'How is an ordinary PostgreSQL protocol message built?', '["A line of text ending in a newline", "A one-byte tag, a length (4 bytes, including itself), and the content", "A JSON object", "Only a length and a body without a tag"]', 1, 'Numbers are sent most significant byte first; in DataRow a length of -1 means NULL.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 43, 1, 'Why must values not be put into SQL by string concatenation?', '["It is slow", "SQL injection is possible: a value with a quote changes the meaning of the query; use parameters $1, $2...", "Postgres does not accept text", "Because of encoding"]', 1, 'Parameters travel in the protocol apart from the query text and are never interpreted as code.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 43, 2, 'How is a column that allows NULL naturally expressed in Rust?', '["By a default value", "By the type Option<T>", "By a panic on read", "By a special string \"NULL\""]', 1, 'The compiler won''t let you forget to handle a missing value.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 43, 3, 'What does Drop do on a transaction guard if commit was not called?', '["Nothing", "Sends ROLLBACK: any error before commit cancels the changes", "Closes the connection", "Commits the transaction"]', 1, 'The rollback is tied to the scope, so it can''t be forgotten in some branch with `?`.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 43, 4, 'What does idempotence of migrations mean?', '["Migrations cannot be rolled back", "A rerun does not apply already applied versions and changes nothing", "They run in parallel", "They do not change the schema"]', 1, 'Recorded numbers of applied versions make it safe to run migrations on every start.');
